/**
 * Python-flavoured exception types.
 *
 * The original script relies on a handful of CPython/Whoosh exceptions leaking
 * through to the user (most visibly `ValueError` from the NUMERIC field range
 * check).  Re-creating them as real classes keeps the control flow of the port
 * identical to the Python original.
 */

export class PyError extends Error {
  constructor(message) {
    super(message);
    this.name = this.constructor.pyname;
  }
}
PyError.pyname = 'Exception';

/** Raised by `int()` and by NUMERIC range validation. */
export class ValueError extends PyError {}
ValueError.pyname = 'ValueError';

/** Raised by `int()` when handed a non-string / non-number. */
export class TypeError_ extends PyError {}
TypeError_.pyname = 'TypeError';

/** Raised inside the query parser when a field cannot parse its text. */
export class QueryParserError extends PyError {}
QueryParserError.pyname = 'QueryParserError';

/** Raised by the schema when an unknown field name is requested. */
export class KeyError extends PyError {}
KeyError.pyname = 'KeyError';

/**
 * Print an uncaught Python-style exception the way CPython does on stderr and
 * exit with status 1 (stdout stays empty).
 */
export function die(err) {
  const name = err instanceof PyError ? err.name : err && err.name ? err.name : 'Exception';
  process.stderr.write(`${name}: ${err && err.message ? err.message : String(err)}\n`);
  process.exit(1);
}

