/**
 * The slices of CPython's built-in semantics that this program depends on:
 * `int(str)` conversion and `repr(str)` (argparse quotes offending values with
 * `repr`).
 */

import { ValueError } from './pyerrors.mjs';

// str.strip() removes ASCII whitespace plus the Unicode space separators.
const PY_SPACE = /^[\s-]+|[\s-]+$/g;

/**
 * `int(s)` for base 10.
 *
 * Accepts surrounding whitespace, an optional sign and `_` digit separators
 * (PEP 515) -- so `int(" +1_000 ")` is 1000 while `int("1.5")` raises.
 */
export function pyInt(value) {
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) throw new ValueError(`cannot convert float ${value} to integer`);
    return Math.trunc(value);
  }
  const raw = String(value);
  const s = raw.replace(PY_SPACE, '');
  // Sign, then digit groups that may be separated -- but never bounded -- by
  // single underscores.
  const m = /^([+-]?)(\d+(?:_\d+)*)$/.exec(s);
  if (!m) {
    throw new ValueError(`invalid literal for int() with base 10: ${pyRepr(raw)}`);
  }
  const digits = m[2].replace(/_/g, '');
  const n = Number(m[1] === '-' ? `-${digits}` : digits);
  if (!Number.isSafeInteger(n)) {
    // Python has arbitrary precision ints; keep the exact value as a BigInt so
    // the range check downstream still reports the literal the user typed.
    return BigInt(m[1] === '-' ? `-${digits}` : digits);
  }
  return n;
}

const REPR_ESCAPES = {
  '\\': '\\\\',
  '\n': '\\n',
  '\r': '\\r',
  '\t': '\\t',
};

/** `repr(s)` for str: prefers single quotes, switches to double when needed. */
export function pyRepr(s) {
  const text = String(s);
  const quote = text.includes("'") && !text.includes('"') ? '"' : "'";
  let out = quote;
  for (const ch of text) {
    if (ch === quote) out += '\\' + ch;
    else if (Object.prototype.hasOwnProperty.call(REPR_ESCAPES, ch)) out += REPR_ESCAPES[ch];
    else if (ch < ' ' || ch === '') out += '\\x' + ch.codePointAt(0).toString(16).padStart(2, '0');
    else out += ch;
  }
  return out + quote;
}

/** `str(int)` -- used by `print(total_price)`. */
export function pyIntStr(n) {
  return typeof n === 'bigint' ? n.toString() : String(n);
}

