/**
 * Tokenizers: the head of an analyzer chain.  They turn a raw field value into
 * a stream of `Token`s.
 */

export class Token {
  constructor(text, pos) {
    this.text = text;
    this.pos = pos;
    this.stopped = false;
  }
}

/**
 * Python's `\w` (with str patterns) is "alphanumeric per str.isalnum(), plus
 * underscore" -- i.e. any letter or number in the Unicode database.  JavaScript's
 * `\w` is ASCII-only, so the class has to be spelled out.
 */
const WORD_CHAR = '[\\p{L}\\p{N}_]';

/**
 * The default whoosh tokenizer: `\w+(\.?\w+)*`, which keeps dotted runs such as
 * `3.14` or `e.g` together but drops a trailing period.
 */
export class RegexTokenizer {
  constructor(expression = `${WORD_CHAR}+(?:\\.?${WORD_CHAR}+)*`) {
    this.expression = expression;
  }

  /**
   * @param {string} value text to split
   * @param {{tokenize?: boolean}} opts when `tokenize` is false the whole value
   *   is emitted as one token (how the parser handles wildcards and ranges).
   */
  tokenize(value, { tokenize = true } = {}) {
    if (!tokenize) return [new Token(value, 0)];
    const re = new RegExp(this.expression, 'gu');
    const tokens = [];
    let match;
    let pos = 0;
    while ((match = re.exec(value)) !== null) {
      if (match[0] === '') {
        re.lastIndex += 1;
        continue;
      }
      tokens.push(new Token(match[0], pos));
      pos += 1;
    }
    return tokens;
  }
}

/** Emits the value unchanged as a single token -- used by the ID field. */
export class IDTokenizer {
  tokenize(value) {
    return [new Token(value, 0)];
  }
}

