/**
 * Token filters: the tail of an analyzer chain.
 */

import { STOP_WORDS } from './stopwords.mjs';

export class LowercaseFilter {
  apply(tokens) {
    for (const t of tokens) t.text = t.text.toLowerCase();
    return tokens;
  }
}

/**
 * Drops stop words and tokens outside [minsize, maxsize].
 *
 * When `removestops` is false the offending tokens are kept but flagged -- that
 * is how the query parser can still build `title:*` out of a one-character
 * "word" that the indexer would have thrown away.
 *
 * Surviving positions are renumbered consecutively (`renumber=True`), which is
 * what makes `"hello world"` a phrase match even across a dropped stop word.
 */
export class StopFilter {
  constructor({ stoplist = STOP_WORDS, minsize = 2, maxsize = null, renumber = true } = {}) {
    this.stoplist = stoplist;
    this.minsize = minsize;
    this.maxsize = maxsize;
    this.renumber = renumber;
  }

  apply(tokens, { removestops = true } = {}) {
    const out = [];
    let pos = null;
    for (const t of tokens) {
      const size = [...t.text].length;
      const keep =
        size >= this.minsize &&
        (this.maxsize === null || size <= this.maxsize) &&
        !this.stoplist.has(t.text);
      if (keep) {
        if (this.renumber) {
          pos = pos === null ? t.pos : pos + 1;
          t.pos = pos;
        }
        t.stopped = false;
        out.push(t);
      } else if (!removestops) {
        t.stopped = true;
        out.push(t);
      }
    }
    return out;
  }
}

