/**
 * Analyzers: a tokenizer followed by zero or more filters.
 */

import { RegexTokenizer, IDTokenizer } from './tokenizers.mjs';
import { LowercaseFilter, StopFilter } from './filters.mjs';
import { STOP_WORDS } from './stopwords.mjs';

export class CompositeAnalyzer {
  constructor(tokenizer, filters = []) {
    this.tokenizer = tokenizer;
    this.filters = filters;
  }

  /**
   * @returns {import('./tokenizers.mjs').Token[]}
   */
  analyze(value, opts = {}) {
    let tokens = this.tokenizer.tokenize(value, opts);
    for (const filter of this.filters) tokens = filter.apply(tokens, opts);
    return tokens;
  }
}

/** `RegexTokenizer | LowercaseFilter | StopFilter` -- the TEXT field default. */
export function StandardAnalyzer({ stoplist = STOP_WORDS, minsize = 2, maxsize = null } = {}) {
  return new CompositeAnalyzer(new RegexTokenizer(), [
    new LowercaseFilter(),
    new StopFilter({ stoplist, minsize, maxsize }),
  ]);
}

/** The ID field analyzer: the value is one atomic term. */
export function IDAnalyzer() {
  return new CompositeAnalyzer(new IDTokenizer(), []);
}

export { STOP_WORDS };

