/**
 * Query objects.
 *
 * Each query knows how to (a) normalize itself into a simpler equivalent and
 * (b) resolve to the set of document numbers it matches against a reader.
 * Scores are computed with BM25 so that `limit=` truncation is meaningful; the
 * matching set itself is what determines this program's output.
 */

const K1 = 1.2;
const B = 0.75;

function bm25(idf, tf, fieldLength, avgFieldLength) {
  const w = tf / (tf + K1 * ((1 - B) + B * (fieldLength / (avgFieldLength || 1))));
  return idf * w;
}

function idf(reader, fieldname, term) {
  const df = reader.docFrequency(fieldname, term);
  const n = reader.docCount();
  return Math.log((n - df + 0.5) / (df + 0.5) + 1.0);
}

export class Query {
  /** @returns {Set<number>} document numbers matching this query. */
  docs() {
    return new Set();
  }

  score() {
    return 1.0;
  }

  normalize() {
    return this;
  }

  isNull() {
    return false;
  }
}

class NullQueryClass extends Query {
  docs() {
    return new Set();
  }

  score() {
    return 0;
  }

  isNull() {
    return true;
  }

  toString() {
    return '<NullQuery>';
  }
}

/** Matches nothing; produced whenever a term is analyzed away. */
export const NullQuery = new NullQueryClass();

export class Term extends Query {
  constructor(fieldname, text, boost = 1.0) {
    super();
    this.fieldname = fieldname;
    this.text = text;
    this.boost = boost;
  }

  docs(reader) {
    return new Set(reader.postings(this.fieldname, this.text).keys());
  }

  score(reader, docnum) {
    const postings = reader.postings(this.fieldname, this.text);
    const hit = postings.get(docnum);
    if (!hit) return 0;
    return (
      this.boost *
      bm25(
        idf(reader, this.fieldname, this.text),
        hit.length,
        reader.docFieldLength(docnum, this.fieldname),
        reader.avgFieldLength(this.fieldname),
      )
    );
  }

  toString() {
    return `${this.fieldname}:${this.text}`;
  }
}

/** Matches every document that has any indexed content in the field. */
export class Every extends Query {
  constructor(fieldname = null, boost = 1.0) {
    super();
    this.fieldname = fieldname;
    this.boost = boost;
  }

  docs(reader) {
    if (this.fieldname === null || this.fieldname === '' || this.fieldname === '*') {
      return new Set(reader.allDocIds());
    }
    return reader.docsInField(this.fieldname);
  }

  score() {
    return this.boost;
  }

  toString() {
    return `${this.fieldname ?? '*'}:*`;
  }
}

/** Base for queries that expand into a set of terms from the field lexicon. */
class ExpandingQuery extends Query {
  constructor(fieldname, boost = 1.0) {
    super();
    this.fieldname = fieldname;
    this.boost = boost;
  }

  /** @returns {Array} the lexicon entries this query covers. */
  expand() {
    return [];
  }

  docs(reader) {
    const out = new Set();
    for (const term of this.expand(reader)) {
      for (const docnum of reader.postings(this.fieldname, term).keys()) out.add(docnum);
    }
    return out;
  }

  score(reader, docnum) {
    let total = 0;
    for (const term of this.expand(reader)) {
      total += new Term(this.fieldname, term, this.boost).score(reader, docnum);
    }
    return total;
  }
}

export class Prefix extends ExpandingQuery {
  constructor(fieldname, text, boost = 1.0) {
    super(fieldname, boost);
    this.text = text;
  }

  expand(reader) {
    return reader.lexicon(this.fieldname).filter((t) => String(t).startsWith(this.text));
  }

  toString() {
    return `${this.fieldname}:${this.text}*`;
  }
}

export class Wildcard extends ExpandingQuery {
  constructor(fieldname, text, boost = 1.0) {
    super(fieldname, boost);
    this.text = text;
  }

  /** `*` matches any run of characters, `?` exactly one; everything else is literal. */
  #regex() {
    let src = '';
    for (const ch of this.text) {
      if (ch === '*') src += '[\\s\\S]*';
      else if (ch === '?') src += '[\\s\\S]';
      else src += ch.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    }
    return new RegExp(`^(?:${src})$`, 'u');
  }

  expand(reader) {
    const re = this.#regex();
    return reader.lexicon(this.fieldname).filter((t) => re.test(String(t)));
  }

  normalize() {
    if (this.text === '*') return new Every(this.fieldname, this.boost);
    if (!this.text.includes('*') && !this.text.includes('?')) {
      return new Term(this.fieldname, this.text, this.boost);
    }
    if (!this.text.includes('?') && this.text.indexOf('*') === this.text.length - 1) {
      return new Prefix(this.fieldname, this.text.slice(0, -1), this.boost);
    }
    return this;
  }

  toString() {
    return `${this.fieldname}:${this.text}`;
  }
}

export class TermRange extends ExpandingQuery {
  constructor(fieldname, start, end, startexcl = false, endexcl = false, boost = 1.0) {
    super(fieldname, boost);
    this.start = start;
    this.end = end;
    this.startexcl = startexcl;
    this.endexcl = endexcl;
  }

  contains(term) {
    if (this.start !== null && this.start !== undefined) {
      if (this.startexcl ? term <= this.start : term < this.start) return false;
    }
    if (this.end !== null && this.end !== undefined) {
      if (this.endexcl ? term >= this.end : term > this.end) return false;
    }
    return true;
  }

  expand(reader) {
    return reader.lexicon(this.fieldname).filter((t) => this.contains(t));
  }

  toString() {
    const open = this.startexcl ? '{' : '[';
    const close = this.endexcl ? '}' : ']';
    return `${this.fieldname}:${open}${this.start ?? ''} TO ${this.end ?? ''}${close}`;
  }
}

/** Same shape as TermRange but compares numerically rather than lexically. */
export class NumericRange extends TermRange {}

export class Phrase extends Query {
  constructor(fieldname, words, slop = 1, boost = 1.0) {
    super();
    this.fieldname = fieldname;
    this.words = words;
    this.slop = slop;
    this.boost = boost;
  }

  normalize() {
    if (this.words.length === 0) return NullQuery;
    if (this.words.length === 1) return new Term(this.fieldname, this.words[0], this.boost);
    return this;
  }

  #hits(reader, docnum) {
    const lists = this.words.map((w) => reader.postings(this.fieldname, w).get(docnum));
    if (lists.some((l) => !l || l.length === 0)) return 0;
    let count = 0;
    for (const start of lists[0]) {
      let pos = start;
      let ok = true;
      for (let i = 1; i < lists.length; i += 1) {
        const next = lists[i].find((p) => p > pos && p - pos <= this.slop);
        if (next === undefined) {
          ok = false;
          break;
        }
        pos = next;
      }
      if (ok) count += 1;
    }
    return count;
  }

  docs(reader) {
    const out = new Set();
    const candidates = reader.postings(this.fieldname, this.words[0]).keys();
    for (const docnum of candidates) {
      if (this.#hits(reader, docnum) > 0) out.add(docnum);
    }
    return out;
  }

  score(reader, docnum) {
    const tf = this.#hits(reader, docnum);
    if (!tf) return 0;
    const avgIdf =
      this.words.reduce((acc, w) => acc + idf(reader, this.fieldname, w), 0) / this.words.length;
    return (
      this.boost *
      bm25(avgIdf, tf, reader.docFieldLength(docnum, this.fieldname), reader.avgFieldLength(this.fieldname))
    );
  }

  toString() {
    return `${this.fieldname}:"${this.words.join(' ')}"`;
  }
}

/* ------------------------------------------------------------------ */
/* Compound queries                                                     */
/* ------------------------------------------------------------------ */

class CompoundQuery extends Query {
  constructor(subqueries, boost = 1.0) {
    super();
    this.subqueries = subqueries;
    this.boost = boost;
  }

  normalizeChildren() {
    return this.subqueries.map((q) => q.normalize());
  }

  score(reader, docnum) {
    return this.subqueries.reduce((acc, q) => acc + q.score(reader, docnum), 0) * this.boost;
  }
}

export class And extends CompoundQuery {
  docs(reader) {
    if (this.subqueries.length === 0) return new Set();
    let acc = null;
    for (const q of this.subqueries) {
      const next = q.docs(reader);
      if (acc === null) acc = next;
      else acc = new Set([...acc].filter((d) => next.has(d)));
      if (acc.size === 0) break;
    }
    return acc ?? new Set();
  }

  normalize() {
    // A NullQuery inside an AND makes the whole conjunction unsatisfiable in
    // whoosh only if it is the sole clause; otherwise it simply drops out.
    const subs = this.normalizeChildren().filter((q) => !q.isNull());
    if (subs.length === 0) return NullQuery;
    if (subs.length === 1) return subs[0];
    return new And(subs, this.boost);
  }

  toString() {
    return `(${this.subqueries.join(' AND ')})`;
  }
}

export class Or extends CompoundQuery {
  docs(reader) {
    const out = new Set();
    for (const q of this.subqueries) for (const d of q.docs(reader)) out.add(d);
    return out;
  }

  normalize() {
    const subs = this.normalizeChildren().filter((q) => !q.isNull());
    if (subs.length === 0) return NullQuery;
    if (subs.length === 1) return subs[0];
    return new Or(subs, this.boost);
  }

  toString() {
    return `(${this.subqueries.join(' OR ')})`;
  }
}

export class Not extends Query {
  constructor(query, boost = 1.0) {
    super();
    this.query = query;
    this.boost = boost;
  }

  docs(reader) {
    const excluded = this.query.docs(reader);
    return new Set(reader.allDocIds().filter((d) => !excluded.has(d)));
  }

  score() {
    return 0;
  }

  normalize() {
    const sub = this.query.normalize();
    return sub.isNull() ? NullQuery : new Not(sub, this.boost);
  }

  toString() {
    return `NOT ${this.query}`;
  }
}

/** `a ANDNOT b` -- documents matching `a` but not `b`. */
export class AndNot extends Query {
  constructor(a, b, boost = 1.0) {
    super();
    this.a = a;
    this.b = b;
    this.boost = boost;
  }

  docs(reader) {
    const negative = this.b.docs(reader);
    return new Set([...this.a.docs(reader)].filter((d) => !negative.has(d)));
  }

  score(reader, docnum) {
    return this.a.score(reader, docnum) * this.boost;
  }

  normalize() {
    const a = this.a.normalize();
    const b = this.b.normalize();
    if (a.isNull()) return NullQuery;
    if (b.isNull()) return a;
    return new AndNot(a, b, this.boost);
  }

  toString() {
    return `(${this.a} ANDNOT ${this.b})`;
  }
}

/** `a ANDMAYBE b` -- documents matching `a`, scored up when they also match `b`. */
export class AndMaybe extends Query {
  constructor(a, b, boost = 1.0) {
    super();
    this.a = a;
    this.b = b;
    this.boost = boost;
  }

  docs(reader) {
    return this.a.docs(reader);
  }

  score(reader, docnum) {
    return (this.a.score(reader, docnum) + this.b.score(reader, docnum)) * this.boost;
  }

  normalize() {
    const a = this.a.normalize();
    const b = this.b.normalize();
    if (a.isNull()) return NullQuery;
    if (b.isNull()) return a;
    return new AndMaybe(a, b, this.boost);
  }

  toString() {
    return `(${this.a} ANDMAYBE ${this.b})`;
  }
}

/** `a REQUIRE b` -- intersection, but only `a` contributes to the score. */
export class Require extends AndNot {
  docs(reader) {
    const required = this.b.docs(reader);
    return new Set([...this.a.docs(reader)].filter((d) => required.has(d)));
  }

  normalize() {
    const a = this.a.normalize();
    const b = this.b.normalize();
    if (a.isNull() || b.isNull()) return NullQuery;
    return new Require(a, b, this.boost);
  }

  toString() {
    return `(${this.a} REQUIRE ${this.b})`;
  }
}

