/**
 * Field types and the schema.
 *
 * A field type decides three things: how a stored value becomes index terms,
 * whether the query parser must hand raw text to the field instead of running
 * it through an analyzer (`selfParsing`), and how values are validated.
 */

import { StandardAnalyzer, IDAnalyzer } from './analysis/analyzers.mjs';
import { ValueError, QueryParserError, KeyError } from './compat/pyerrors.mjs';
import { pyInt } from './compat/pyint.mjs';
import { Term, Every, NumericRange } from './query/queries.mjs';

export class FieldType {
  constructor({ stored = false, unique = false, fieldBoost = 1.0 } = {}) {
    this.stored = stored;
    this.unique = unique;
    this.fieldBoost = fieldBoost;
    this.indexed = true;
    this.analyzer = null;
    this.numeric = false;
  }

  /** True when the field parses query text itself (NUMERIC, DATETIME, ...). */
  selfParsing() {
    return false;
  }

  /** Run query/index text through the analyzer, returning bare strings. */
  processText(text, { tokenize = true, removestops = true } = {}) {
    if (!this.analyzer) return [String(text)];
    return this.analyzer.analyze(String(text), { tokenize, removestops }).map((t) => t.text);
  }

  /**
   * @returns {Array<{term: *, positions: number[]}>} postings for one value.
   */
  index(value) {
    const grouped = new Map();
    for (const token of this.analyzer.analyze(String(value), { tokenize: true, removestops: true })) {
      if (!grouped.has(token.text)) grouped.set(token.text, []);
      grouped.get(token.text).push(token.pos);
    }
    return [...grouped].map(([term, positions]) => ({ term, positions }));
  }

  /** The value handed back by `hit["fieldname"]`. */
  toStored(value) {
    return value;
  }
}

export class TEXT extends FieldType {
  constructor({ analyzer = null, phrase = true, stored = false, fieldBoost = 1.0, sortable = false } = {}) {
    super({ stored, fieldBoost });
    this.analyzer = analyzer || StandardAnalyzer();
    this.phrase = phrase;
    this.sortable = sortable;
  }
}

export class ID extends FieldType {
  constructor({ stored = false, unique = false, fieldBoost = 1.0, sortable = false } = {}) {
    super({ stored, unique, fieldBoost });
    this.analyzer = IDAnalyzer();
    this.sortable = sortable;
  }
}

export class KEYWORD extends FieldType {
  constructor({ stored = false, lowercase = false, commas = false, scorable = false } = {}) {
    super({ stored });
    this.analyzer = StandardAnalyzer({ minsize: 1, stoplist: new Set() });
    this.lowercase = lowercase;
    this.commas = commas;
    this.scorable = scorable;
  }
}

/**
 * A numeric field.  Defaults to 32-bit signed integers, so values outside
 * [-2^31, 2^31-1] raise `ValueError` when the document is added.
 */
export class NUMERIC extends FieldType {
  constructor({ numtype = 'int', bits = 32, stored = false, unique = false, signed = true, decimalPlaces = 0 } = {}) {
    super({ stored, unique });
    this.numtype = numtype;
    this.bits = numtype === 'float' ? 64 : bits;
    this.signed = signed;
    this.decimalPlaces = decimalPlaces;
    this.numeric = true;
    if (numtype === 'float') {
      this.minValue = -Infinity;
      this.maxValue = Infinity;
    } else if (signed) {
      this.minValue = -(2 ** (this.bits - 1));
      this.maxValue = 2 ** (this.bits - 1) - 1;
    } else {
      this.minValue = 0;
      this.maxValue = 2 ** this.bits - 1;
    }
  }

  selfParsing() {
    return true;
  }

  /** `NUMERIC.prepare_number` -- coerce to the numeric type and range-check. */
  prepareNumber(x) {
    if (x === null || x === undefined) return x;
    const n = this.numtype === 'float' ? Number(x) : pyInt(x);
    if (this.numtype === 'float' && Number.isNaN(n)) {
      throw new ValueError(`could not convert string to float: ${JSON.stringify(String(x))}`);
    }
    const tooSmall = typeof n === 'bigint' ? n < BigInt(this.minValue) : n < this.minValue;
    const tooBig = typeof n === 'bigint' ? n > BigInt(this.maxValue) : n > this.maxValue;
    if (tooSmall || tooBig) {
      throw new ValueError(
        `Numeric field value ${n} out of range [${this.minValue}, ${this.maxValue}]`,
      );
    }
    return Number(n);
  }

  index(value) {
    return [{ term: this.prepareNumber(value), positions: [0] }];
  }

  toStored(value) {
    return this.prepareNumber(value);
  }

  /** Query text for a numeric field is a literal, not something to tokenize. */
  parseQuery(fieldname, qstring, boost = 1.0) {
    if (qstring === '*') return new Every(fieldname, boost);
    let value;
    try {
      value = this.prepareNumber(qstring);
    } catch (err) {
      throw new QueryParserError(err.message);
    }
    return new Term(fieldname, value, boost);
  }

  parseRange(fieldname, start, end, startexcl, endexcl, boost = 1.0) {
    try {
      const lo = start === null || start === undefined ? null : this.prepareNumber(start);
      const hi = end === null || end === undefined ? null : this.prepareNumber(end);
      return new NumericRange(fieldname, lo, hi, startexcl, endexcl, boost);
    } catch (err) {
      throw new QueryParserError(err.message);
    }
  }
}

export class BOOLEAN extends FieldType {
  constructor({ stored = false } = {}) {
    super({ stored });
  }

  selfParsing() {
    return true;
  }

  index(value) {
    return [{ term: value ? 't' : 'f', positions: [0] }];
  }

  parseQuery(fieldname, qstring, boost = 1.0) {
    return new Term(fieldname, /^(t|true|yes|1)$/i.test(qstring) ? 't' : 'f', boost);
  }
}

export class Schema {
  /** @param {Record<string, FieldType>} fields */
  constructor(fields = {}) {
    this._fields = new Map();
    for (const name of Object.keys(fields).sort()) this._fields.set(name, fields[name]);
  }

  has(name) {
    return this._fields.has(name);
  }

  get(name) {
    if (!this._fields.has(name)) throw new KeyError(`No field named ${name}`);
    return this._fields.get(name);
  }

  names() {
    return [...this._fields.keys()];
  }

  storedNames() {
    return this.names().filter((n) => this._fields.get(n).stored);
  }

  *[Symbol.iterator]() {
    yield* this._fields.values();
  }
}

