  parseRange(fieldname, start, end, startexcl, endexcl, boost = 1.0) {
    try {
      const lo = start === null || start === undefined ? null : this.prepareNumber(start);
      const hi = end === null || end === undefined ? null : this.prepareNumber(end);
      return new NumericRange(fieldname, lo, hi, startexcl, endexcl, boost);
    } catch (err) {
