export class FieldnameNode extends SyntaxNode {
  constructor(fieldname, original) {
    super();
    this.fieldname = fieldname;
    this.original = original;
  }
}

export class WhitespaceNode extends SyntaxNode {
  constructor(text) {
    super();
    this.original = text;
  }
}

export class OpenBracket extends SyntaxNode {
  constructor() {
    super();
    this.original = '(';
  }
}

export class CloseBracket extends SyntaxNode {
  constructor() {
    super();
    this.original = ')';
  }
}

export class BoostNode extends SyntaxNode {
  constructor(boostValue, original) {
    super();
    this.boostValue = boostValue;
    this.original = original;
  }
}

/** An operator token waiting to be turned into a group by `doOperators`. */
export class OperatorNode extends SyntaxNode {
  constructor(spec, original) {
    super();
    this.spec = spec;
    this.original = original;
  }
}

/* ------------------------------------------------------------------ */
/* Groups                                                              */
/* ------------------------------------------------------------------ */

export class GroupNode extends SyntaxNode {
  constructor(nodes = []) {
    super();
