/**
 * Taggers: regular expressions that claim a slice of the query string and turn
 * it into a syntax node.
 *
 * They are tried in ascending priority order at each character position; the
 * first that matches wins, and any text skipped over in between becomes a
 * plain word.
 */

import {
  WordNode,
  WildcardNode,
  PhraseNode,
  RangeNode,
  EveryNode,
  FieldnameNode,
  WhitespaceNode,
  OpenBracket,
  CloseBracket,
  BoostNode,
  OperatorNode,
} from './syntax.mjs';

// Python's `\w` for str patterns.
const W = '[\\p{L}\\p{N}_]';

class Tagger {
  /**
   * @param {string} expr regex source, matched with the sticky flag
   * @param {(m: RegExpExecArray) => import('./syntax.mjs').SyntaxNode|null} build
   */
  constructor(expr, priority, build) {
    this.regex = new RegExp(expr, 'yu');
    this.priority = priority;
    this.build = build;
  }

  match(text, pos) {
    this.regex.lastIndex = pos;
    const m = this.regex.exec(text);
    if (!m || m[0] === '') return null;
    const node = this.build(m);
    if (node === null) return null;
    node.startchar = pos;
    node.endchar = pos + m[0].length;
    return node;
  }
}

/**
 * The default plugin set of `whoosh.qparser.QueryParser`, flattened into
 * taggers.  Ties in priority are broken by the order plugins are registered.
 */
export const DEFAULT_TAGGERS = [
  // OperatorsPlugin registers ANDNOT/ANDMAYBE ahead of the rest so they are not
  // shadowed by the plain AND tagger.
  new Tagger('(?<=\\s)ANDNOT(?=\\s)', -5, () => new OperatorNode('andnot', 'ANDNOT')),
  new Tagger('(?<=\\s)ANDMAYBE(?=\\s)', -5, () => new OperatorNode('andmaybe', 'ANDMAYBE')),

  // EveryPlugin
  new Tagger('[*]:[*]', -1, () => new EveryNode()),

  // SingleQuotePlugin
  new Tagger("(?<=^|\\W)'(.*?)'(?=\\s|\\]|[)}]|$)", 0, (m) => new WordNode(m[1])),

  // FieldsPlugin
  new Tagger(`(${W}+|[*]):(?![ \\t\\r\\n])`, 0, (m) => new FieldnameNode(m[1], m[0])),

  // WildcardPlugin
  new Tagger('[*?]', 0, (m) => new WildcardNode(m[0])),

  // PhrasePlugin
  new Tagger('"(.*?)(?<!\\\\)"', 0, (m) => new PhraseNode(m[1])),

  // GroupPlugin
  new Tagger('\\(', 0, () => new OpenBracket()),
  new Tagger('\\)', 0, () => new CloseBracket()),

  // OperatorsPlugin (the rest)
  new Tagger('(?<=^|\\s|[()])NOT(?=\\s)', 0, () => new OperatorNode('not', 'NOT')),
  new Tagger('(?<=\\s)AND(?=\\s)', 0, () => new OperatorNode('and', 'AND')),
  new Tagger('(?<=\\s)OR(?=\\s)', 0, () => new OperatorNode('or', 'OR')),
  new Tagger('(?<=^|\\s)REQUIRE(?=\\s)', 0, () => new OperatorNode('require', 'REQUIRE')),

  // BoostPlugin
  new Tagger('\\^([0-9]*(?:\\.[0-9]+)?)(?:$|(?=[ \\t\\r\\n]))', 0, (m) => {
    const value = m[1] === '' ? 1.0 : Number(m[1]);
    return new BoostNode(value, m[0]);
  }),

  // RangePlugin
  new Tagger(
    "([{[])" +
      "((?:'[^']*?')|(?:[^\\]}]+?(?=[Tt][Oo])))?" +
      '\\s*[Tt][Oo]\\s*' +
      "((?:'[^']*?')|(?:[^\\]}]+?))?" +
      '([}\\]])',
    1,
    (m) => {
      const strip = (s) => {
        if (s === undefined) return null;
        const t = s.replace(/^\s+|\s+$/g, '');
        if (t.length >= 2 && t.startsWith("'") && t.endsWith("'")) return t.slice(1, -1);
        return t === '' ? null : t;
      };
      return new RangeNode(strip(m[2]), strip(m[3]), m[1] === '{', m[4] === '}');
    },
  ),

  // WhitespacePlugin -- lowest priority, so everything else gets first refusal.
  new Tagger('\\s+', 100, (m) => new WhitespaceNode(m[0])),
].sort((a, b) => a.priority - b.priority);

/**
 * Scan `text` left to right, emitting tagged nodes and turning the gaps in
 * between into word nodes.
 */
export function tag(text, taggers = DEFAULT_TAGGERS) {
  const nodes = [];
  let pos = 0;
  let prev = 0;
  while (pos < text.length) {
    let node = null;
    for (const tagger of taggers) {
      node = tagger.match(text, pos);
      if (node) break;
    }
    if (node) {
      if (prev < pos) nodes.push(new WordNode(text.slice(prev, pos)));
      nodes.push(node);
      prev = node.endchar;
      pos = node.endchar;
    } else {
      pos += 1;
    }
  }
  if (prev < text.length) nodes.push(new WordNode(text.slice(prev)));
  return nodes;
}

