/**
 * `whoosh.qparser.QueryParser`.
 *
 * `parse()` runs the tagging pass, then the filter chain (in whoosh's priority
 * order: groups, boost cleanup, wildcards, fieldnames, whitespace removal,
 * operators, boost application), then builds and normalizes the query tree.
 */

import * as syntax from './syntax.mjs';
import { tag } from './taggers.mjs';
import * as q from '../query/queries.mjs';
import { QueryParserError } from '../compat/pyerrors.mjs';

/** Operators in the order whoosh applies them (ANDNOT/ANDMAYBE bind first). */
const OPERATORS = [
  { spec: 'andnot', kind: 'infix', group: syntax.AndNotGroup },
  { spec: 'andmaybe', kind: 'infix', group: syntax.AndMaybeGroup },
  { spec: 'not', kind: 'prefix', group: syntax.NotGroup },
  { spec: 'and', kind: 'infix', group: syntax.AndGroup },
  { spec: 'or', kind: 'infix', group: syntax.OrGroup },
  { spec: 'require', kind: 'infix', group: syntax.RequireGroup },
];

export class QueryParser {
  /**
   * @param {string} fieldname default field for bare terms
   * @param {import('../fields.mjs').Schema} schema
   */
  constructor(fieldname, schema, { group = syntax.AndGroup, termclass = q.Term, removeUnknown = true } = {}) {
    this.fieldname = fieldname;
    this.schema = schema;
    this.group = group;
    this.termclass = termclass;
    this.phraseclass = q.Phrase;
    this.removeUnknown = removeUnknown;
  }

  parse(text, { normalize = true } = {}) {
    const tree = this.process(String(text));
    let query = tree.query(this);
    if (!query) query = q.NullQuery;
    return normalize ? query.normalize() : query;
  }

  process(text) {
    let group = this.#doGroups(tag(text));
    group = this.#cleanBoost(group);
    group = this.#doWildcards(group);
    group = this.#doFieldnames(group);
    group = this.#removeWhitespace(group);
    group = this.#doOperators(group);
    group = this.#doBoost(group);
    return group;
  }

  /* ---------------- filters ---------------- */

  /** Fold `(` ... `)` runs into nested groups. Unbalanced brackets are ignored. */
  #doGroups(nodes) {
    const root = new this.group([]);
    const stack = [root];
    for (const node of nodes) {
      if (node instanceof syntax.OpenBracket) {
        const child = new this.group([]);
        stack[stack.length - 1].nodes.push(child);
        stack.push(child);
      } else if (node instanceof syntax.CloseBracket) {
        if (stack.length > 1) stack.pop();
      } else {
        stack[stack.length - 1].nodes.push(node);
      }
    }
    return root;
  }

  /** A `^2` with nothing boostable in front of it is just a word. */
  #cleanBoost(group) {
    group.nodes.forEach((node, i) => {
      if (node instanceof syntax.GroupNode) this.#cleanBoost(node);
      else if (node instanceof syntax.BoostNode && (i === 0 || !group.nodes[i - 1].hasBoost)) {
        group.nodes[i] = syntax.toWord(node);
      }
    });
    return group;
  }

  /** Glue `*`/`?` onto the text nodes they touch, then simplify to prefixes. */
  #doWildcards(group) {
    const nodes = group.nodes;
    let i = 0;
    while (i < nodes.length) {
      const node = nodes[i];
      if (node instanceof syntax.WildcardNode) {
        if (i < nodes.length - 1 && nodes[i + 1].isText()) {
          node.text += nodes.splice(i + 1, 1)[0].text;
        }
        if (i > 0 && nodes[i - 1].isText()) {
          node.text = nodes.splice(i - 1, 1)[0].text + node.text;
        } else {
          i += 1;
        }
      } else {
        if (node instanceof syntax.GroupNode) this.#doWildcards(node);
        i += 1;
      }
    }
    nodes.forEach((node, idx) => {
      if (node instanceof syntax.WildcardNode) {
        const text = node.text;
        if (text.length > 1 && !text.includes('?') && text.indexOf('*') === text.length - 1) {
          const prefix = new syntax.PrefixNode(text.slice(0, -1));
          prefix.fieldname = node.fieldname;
          nodes[idx] = prefix;
        }
      }
    });
    return group;
  }

  /**
   * Apply each `field:` tag to the node that follows it.
   *
   * Tags naming a field the schema does not know are folded back into the
   * following word (`zz:the` searches the default field for `zz the`), and a
   * tag with nothing after it becomes a literal word.
   */
  #doFieldnames(group) {
    let nodes = group.nodes;

    if (this.removeUnknown && this.schema) {
      const kept = [];
      let pending = null;
      for (const node of nodes) {
        if (node instanceof syntax.FieldnameNode && !this.schema.has(node.fieldname)) {
          pending = node;
          continue;
        }
        if (pending) {
          kept.push(node.isText() ? new syntax.WordNode(pending.original + node.text) : node);
          pending = null;
          continue;
        }
        kept.push(node);
      }
      if (pending) kept.push(syntax.toWord(pending));
      nodes = kept;
    }

    const out = [];
    for (let i = 0; i < nodes.length; i += 1) {
      const node = nodes[i];
      if (node instanceof syntax.FieldnameNode) {
        const next = nodes[i + 1];
        if (next && next.hasFieldname) {
          next.setFieldname(node.fieldname, true);
          if (next instanceof syntax.GroupNode) this.#applyFieldname(next, node.fieldname);
          out.push(next);
          i += 1;
        } else {
          out.push(syntax.toWord(node));
        }
        continue;
      }
      if (node instanceof syntax.GroupNode) this.#doFieldnames(node);
      out.push(node);
    }
    group.nodes = out;
    return group;
  }

  /** `content:(item1 OR item2)` pushes the field down into every member. */
  #applyFieldname(group, fieldname) {
    for (const node of group.nodes) {
      if (node instanceof syntax.GroupNode) this.#applyFieldname(node, fieldname);
      else if (node.hasFieldname) node.setFieldname(fieldname, false);
    }
  }

  #removeWhitespace(group) {
    group.nodes = group.nodes.filter((node) => {
      if (node instanceof syntax.GroupNode) this.#removeWhitespace(node);
      return !(node instanceof syntax.WhitespaceNode);
    });
    return group;
  }

  #doOperators(group) {
    for (const node of group.nodes) {
      if (node instanceof syntax.GroupNode) this.#doOperators(node);
    }
    for (const op of OPERATORS) {
      const nodes = group.nodes;
      let i = 0;
      while (i < nodes.length) {
        const node = nodes[i];
        if (!(node instanceof syntax.OperatorNode) || node.spec !== op.spec) {
          i += 1;
          continue;
        }
        if (op.kind === 'prefix') {
          nodes.splice(i, 1);
          if (i < nodes.length) nodes[i] = new op.group([nodes[i]]);
          continue;
        }
        if (i > 0 && i < nodes.length - 1) {
          const left = nodes[i - 1];
          const right = nodes[i + 1];
          // `a AND b AND c` collapses into one n-ary group rather than nesting.
          if (left instanceof op.group && left.merging) {
            left.nodes.push(right);
            nodes.splice(i, 2);
            i -= 1;
          } else if (right instanceof op.group && right.merging) {
            right.nodes.unshift(left);
            nodes.splice(i - 1, 2);
            i -= 1;
          } else {
            nodes.splice(i - 1, 3, new op.group([left, right]));
          }
        } else {
          nodes.splice(i, 1);
        }
      }
    }
    return group;
  }

  #doBoost(group) {
    const out = [];
    for (let node of group.nodes) {
      if (node instanceof syntax.GroupNode) node = this.#doBoost(node);
      else if (node instanceof syntax.BoostNode) {
        if (out.length && out[out.length - 1].hasBoost) {
          out[out.length - 1].boost = node.boostValue;
          continue;
        }
        node = syntax.toWord(node);
      }
      out.push(node);
    }
    group.nodes = out;
    return group;
  }

  /* ---------------- query construction ---------------- */

  /**
   * Turn one chunk of text into a query, letting the field decide how.
   *
   * Text that analyzes down to nothing (a stop word, or a token below the
   * minimum size) becomes `NullQuery`; text that analyzes to several tokens is
   * combined with the parser's default group.
   */
  termQuery(fieldname, text, termclass, { boost = 1.0, tokenize = true, removestops = true } = {}) {
    if (this.schema && this.schema.has(fieldname)) {
      const field = this.schema.get(fieldname);
      if (field.selfParsing()) {
        try {
          return field.parseQuery(fieldname, text, boost);
        } catch (err) {
          if (err instanceof QueryParserError) return q.NullQuery;
          throw err;
        }
      }
      const texts = field.processText(text, { tokenize, removestops });
      if (texts.length > 1) return this.multitokenQuery(texts, fieldname, termclass, boost);
      if (texts.length === 0) return q.NullQuery;
      return new termclass(fieldname, texts[0], boost);
    }
    return new termclass(fieldname, text, boost);
  }

  multitokenQuery(texts, fieldname, termclass, boost) {
    const terms = texts.map((t) => new termclass(fieldname, t, boost));
    return this.group === syntax.OrGroup ? new q.Or(terms) : new q.And(terms);
  }
}

export { syntax };
export const AndGroup = syntax.AndGroup;
export const OrGroup = syntax.OrGroup;

