/**
 * Query-syntax nodes.
 *
 * Parsing happens in two phases: a tagging phase turns the raw string into a
 * flat list of these nodes, then a series of filters rearranges them into a
 * tree.  Finally each node knows how to turn itself into a `Query`.
 */

import * as q from '../query/queries.mjs';
import { QueryParserError } from '../compat/pyerrors.mjs';

export class SyntaxNode {
  constructor() {
    this.fieldname = null;
    this.boost = 1.0;
    this.hasFieldname = false;
    this.hasBoost = false;
    this.original = '';
  }

  isText() {
    return false;
  }

  setFieldname(name, override = false) {
    if (!this.hasFieldname) return this;
    if (override || this.fieldname === null) this.fieldname = name;
    return this;
  }

  query() {
    return null;
  }
}

/** Base for anything carrying analyzable text. */
export class TextNode extends SyntaxNode {
  constructor(text) {
    super();
    this.text = text;
    this.original = text;
    this.hasFieldname = true;
    this.hasBoost = true;
    this.tokenize = true;
    this.removestops = true;
    this.qclass = null;
  }

  isText() {
    return true;
  }

  query(parser) {
    const fieldname = this.fieldname || parser.fieldname;
    const termclass = this.qclass || parser.termclass;
    return parser.termQuery(fieldname, this.text, termclass, {
      boost: this.boost,
      tokenize: this.tokenize,
      removestops: this.removestops,
    });
  }
}

export class WordNode extends TextNode {}

/** A `*` or `?` -- merged with neighbouring text by the wildcard filter. */
export class WildcardNode extends TextNode {
  constructor(text) {
    super(text);
    this.tokenize = false;
    this.removestops = false;
    this.qclass = q.Wildcard;
  }
}

export class PrefixNode extends TextNode {
  constructor(text) {
    super(text);
    this.tokenize = false;
    this.removestops = false;
    this.qclass = q.Prefix;
  }
}

/** `"one two three"` */
export class PhraseNode extends SyntaxNode {
  constructor(text, slop = 1) {
    super();
    this.text = text;
    this.original = `"${text}"`;
    this.slop = slop;
    this.hasFieldname = true;
    this.hasBoost = true;
  }

  query(parser) {
    const fieldname = this.fieldname || parser.fieldname;
    if (parser.schema && parser.schema.has(fieldname)) {
      const field = parser.schema.get(fieldname);
      if (field.selfParsing()) {
        try {
          return field.parseQuery(fieldname, this.text, this.boost);
        } catch (err) {
          if (err instanceof QueryParserError) return q.NullQuery;
          throw err;
        }
      }
      const words = field.processText(this.text, { tokenize: true, removestops: true });
      return new q.Phrase(fieldname, words, this.slop, this.boost);
    }
    return new q.Phrase(fieldname, this.text.split(/\s+/).filter(Boolean), this.slop, this.boost);
  }
}

/** `[start TO end]` / `{start TO end}` */
export class RangeNode extends SyntaxNode {
  constructor(start, end, startexcl, endexcl) {
    super();
    this.start = start;
    this.end = end;
    this.startexcl = startexcl;
    this.endexcl = endexcl;
    this.hasFieldname = true;
    this.hasBoost = true;
    this.original = `${startexcl ? '{' : '['}${start ?? ''} TO ${end ?? ''}${endexcl ? '}' : ']'}`;
  }

  query(parser) {
    const fieldname = this.fieldname || parser.fieldname;
    let { start, end } = this;
    if (parser.schema && parser.schema.has(fieldname)) {
      const field = parser.schema.get(fieldname);
      if (field.selfParsing()) {
        try {
          return field.parseRange(fieldname, start, end, this.startexcl, this.endexcl, this.boost);
        } catch (err) {
          if (err instanceof QueryParserError) return q.NullQuery;
          throw err;
        }
      }
      // Ranges are not tokenized -- the bound is a single lexicon entry.
      if (start) start = field.processText(start, { tokenize: false, removestops: false })[0] ?? null;
      if (end) end = field.processText(end, { tokenize: false, removestops: false })[0] ?? null;
    }
    if (start || end) {
      return new q.TermRange(fieldname, start ?? null, end ?? null, this.startexcl, this.endexcl, this.boost);
    }
    return new q.Every(fieldname, this.boost);
  }
}

/** `*:*` */
export class EveryNode extends SyntaxNode {
  constructor() {
    super();
    this.original = '*:*';
    this.hasBoost = true;
  }

  query() {
    return new q.Every(null, this.boost);
  }
}

/** `fieldname:` -- consumed by the fieldname filter. */
export class FieldnameNode extends SyntaxNode {
  constructor(fieldname, original) {
    super();
    this.fieldname = fieldname;
    this.original = original;
  }
}

export class WhitespaceNode extends SyntaxNode {
  constructor(text) {
    super();
    this.original = text;
  }
}

export class OpenBracket extends SyntaxNode {
  constructor() {
    super();
    this.original = '(';
  }
}

export class CloseBracket extends SyntaxNode {
  constructor() {
    super();
    this.original = ')';
  }
}

export class BoostNode extends SyntaxNode {
  constructor(boostValue, original) {
    super();
    this.boostValue = boostValue;
    this.original = original;
  }
}

/** An operator token waiting to be turned into a group by `doOperators`. */
export class OperatorNode extends SyntaxNode {
  constructor(spec, original) {
    super();
    this.spec = spec;
    this.original = original;
  }
}

/* ------------------------------------------------------------------ */
/* Groups                                                              */
/* ------------------------------------------------------------------ */

export class GroupNode extends SyntaxNode {
  constructor(nodes = []) {
    super();
    this.nodes = nodes;
    this.hasBoost = true;
    this.merging = true;
  }

  get length() {
    return this.nodes.length;
  }

  empty() {
    return new this.constructor([]);
  }

  subQueries(parser) {
    return this.nodes.map((n) => n.query(parser)).filter((x) => x !== null && x !== undefined);
  }
}

export class AndGroup extends GroupNode {
  query(parser) {
    return new q.And(this.subQueries(parser), this.boost);
  }
}

export class OrGroup extends GroupNode {
  query(parser) {
    return new q.Or(this.subQueries(parser), this.boost);
  }
}

export class NotGroup extends GroupNode {
  constructor(nodes = []) {
    super(nodes);
    this.merging = false;
  }

  query(parser) {
    const subs = this.subQueries(parser);
    return subs.length ? new q.Not(subs[0], this.boost) : q.NullQuery;
  }
}

class BinaryGroup extends GroupNode {
  constructor(nodes = []) {
    super(nodes);
    this.merging = false;
  }
}

export class AndNotGroup extends BinaryGroup {
  query(parser) {
    const subs = this.subQueries(parser);
    return subs.length === 2 ? new q.AndNot(subs[0], subs[1], this.boost) : q.NullQuery;
  }
}

export class AndMaybeGroup extends BinaryGroup {
  query(parser) {
    const subs = this.subQueries(parser);
    return subs.length === 2 ? new q.AndMaybe(subs[0], subs[1], this.boost) : q.NullQuery;
  }
}

export class RequireGroup extends BinaryGroup {
  query(parser) {
    const subs = this.subQueries(parser);
    return subs.length === 2 ? new q.Require(subs[0], subs[1], this.boost) : q.NullQuery;
  }
}

/**
 * Turn any node back into the literal text it was tagged from.
 *
 * Used when a tag turns out not to mean what it looked like -- an unknown
 * `foo:` prefix, or a `^2` that has nothing to boost.
 */
export function toWord(node) {
  return new WordNode(node.original);
}

