  lexicon(fieldname) {
    if (!this._lexicons.has(fieldname)) {
      const bucket = this.#field(fieldname);
      const terms = bucket ? [...bucket.terms.keys()] : [];
      terms.sort(bucket && bucket.numeric ? (a, b) => a - b : undefined);
      this._lexicons.set(fieldname, terms);
    }
    return this._lexicons.get(fieldname);
