/**
 * Segment storage: the inverted index itself, plus the reader that queries run
 * against.
 *
 * A segment holds, per field, a term -> {docnum -> positions} mapping, the
 * per-document field lengths used for scoring, and the stored field values
 * returned by hits.  It serializes to JSON so a committed index really does
 * live in the directory `create_in()` was pointed at.
 */

export class Segment {
  constructor(schema) {
    this.schema = schema;
    this.docCount = 0;
    /** @type {Array<Record<string, *>>} */
    this.stored = [];
    /** @type {Map<string, {terms: Map<*, Map<number, number[]>>, lengths: Map<number, number>, numeric: boolean}>} */
    this.fields = new Map();
    for (const name of schema.names()) {
      this.fields.set(name, { terms: new Map(), lengths: new Map(), numeric: schema.get(name).numeric });
    }
  }

  addDocument(values) {
    const docnum = this.docCount;
    const storedValues = {};
    for (const [name, value] of Object.entries(values)) {
      const field = this.schema.get(name);
      const bucket = this.fields.get(name);
      let length = 0;
      if (field.indexed) {
        for (const { term, positions } of field.index(value)) {
          if (!bucket.terms.has(term)) bucket.terms.set(term, new Map());
          bucket.terms.get(term).set(docnum, positions);
          length += positions.length;
        }
      }
      bucket.lengths.set(docnum, length);
      if (field.stored) storedValues[name] = field.toStored(value);
    }
    this.stored.push(storedValues);
    this.docCount += 1;
    return docnum;
  }

  toJSON() {
    const fields = {};
    for (const [name, bucket] of this.fields) {
      fields[name] = {
        numeric: bucket.numeric,
        terms: [...bucket.terms].map(([term, postings]) => [term, [...postings]]),
        lengths: [...bucket.lengths],
      };
    }
    return { docCount: this.docCount, stored: this.stored, fields };
  }

  static fromJSON(schema, data) {
    const segment = new Segment(schema);
    segment.docCount = data.docCount;
    segment.stored = data.stored;
    segment.fields = new Map();
    for (const [name, raw] of Object.entries(data.fields)) {
      segment.fields.set(name, {
        numeric: raw.numeric,
        terms: new Map(raw.terms.map(([term, postings]) => [term, new Map(postings)])),
        lengths: new Map(raw.lengths),
      });
    }
    return segment;
  }
}

const EMPTY_POSTINGS = new Map();

export class Reader {
  constructor(segment) {
    this.segment = segment;
    this._lexicons = new Map();
