    return Array.from({ length: this.segment.docCount }, (_, i) => i);
  }

  #field(fieldname) {
    return this.segment.fields.get(fieldname);
  }

  /** Sorted list of every term indexed in a field. */
  lexicon(fieldname) {
    if (!this._lexicons.has(fieldname)) {
      const bucket = this.#field(fieldname);
      const terms = bucket ? [...bucket.terms.keys()] : [];
      terms.sort(bucket && bucket.numeric ? (a, b) => a - b : undefined);
      this._lexicons.set(fieldname, terms);
    }
    return this._lexicons.get(fieldname);
  }

  /** @returns {Map<number, number[]>} docnum -> positions. */
  postings(fieldname, term) {
    const bucket = this.#field(fieldname);
    if (!bucket) return EMPTY_POSTINGS;
    return bucket.terms.get(term) || EMPTY_POSTINGS;
  }

  docFrequency(fieldname, term) {
    return this.postings(fieldname, term).size;
  }

  /** Documents with at least one indexed term in the field. */
  docsInField(fieldname) {
    const out = new Set();
    const bucket = this.#field(fieldname);
    if (!bucket) return out;
    for (const postings of bucket.terms.values()) {
      for (const docnum of postings.keys()) out.add(docnum);
    }
    return out;
  }

  docFieldLength(docnum, fieldname) {
    const bucket = this.#field(fieldname);
    return (bucket && bucket.lengths.get(docnum)) || 0;
  }

  avgFieldLength(fieldname) {
    if (!this._avgLengths.has(fieldname)) {
      const bucket = this.#field(fieldname);
      let total = 0;
      if (bucket) for (const len of bucket.lengths.values()) total += len;
      this._avgLengths.set(fieldname, this.docCount() ? total / this.docCount() : 0);
    }
    return this._avgLengths.get(fieldname);
  }

  storedFields(docnum) {
    return this.segment.stored[docnum] || {};
  }
