/**
 * `ix.writer()` -- buffers documents and flushes them to the index directory on
 * `commit()`.
 */

import { Segment } from './store.mjs';

export class IndexWriter {
  constructor(index) {
    this.index = index;
    this.schema = index.schema;
    this.segment = new Segment(index.schema);
    this.closed = false;
  }

  /**
   * @param {Record<string, *>} values field name -> value, exactly the keyword
   *   arguments the Python call passes.
   */
  addDocument(values) {
    if (this.closed) throw new Error('This writer is closed');
    for (const name of Object.keys(values)) {
      // Raises KeyError for unknown fields, as whoosh does.
      this.schema.get(name);
    }
    return this.segment.addDocument(values);
  }

  commit() {
    this.index._writeSegment(this.segment);
    this.closed = true;
  }

  cancel() {
    this.closed = true;
  }
}

