/**
 * `ix.searcher()`, plus the `Results` / `Hit` objects it returns.
 */

import { Reader } from './store.mjs';

/** One search result. `hit.get(name)` is Python's `hit["name"]`. */
export class Hit {
  constructor(reader, docnum, score, rank) {
    this.reader = reader;
    this.docnum = docnum;
    this.score = score;
    this.rank = rank;
  }

  fields() {
    return this.reader.storedFields(this.docnum);
  }

  get(name, fallback = undefined) {
    const stored = this.fields();
    return name in stored ? stored[name] : fallback;
  }
}

/** An iterable, indexable list of hits ordered by descending score. */
export class Results {
  constructor(hits, totalMatched) {
    this.hits = hits;
    this.totalMatched = totalMatched;
  }

  get length() {
    return this.hits.length;
  }

  scoredLength() {
    return this.hits.length;
  }

  /** Total number of matching documents, ignoring `limit`. */
  estimatedLength() {
    return this.totalMatched;
  }

  [Symbol.iterator]() {
    return this.hits[Symbol.iterator]();
  }
}

export class Searcher {
  constructor(index) {
    this.index = index;
    this.schema = index.schema;
    this.reader = new Reader(index._segment());
    this.closed = false;
  }

  docCount() {
    return this.reader.docCount();
  }

  /**
   * @param {import('../query/queries.mjs').Query} query
   * @param {{limit?: number|null}} options `limit` caps the hits returned; null
   *   means "all of them".
   */
  search(query, { limit = 10 } = {}) {
    const matched = [...query.docs(this.reader)].sort((a, b) => a - b);
    const scored = matched.map((docnum) => ({ docnum, score: query.score(this.reader, docnum) }));
    // Ties keep document order, which is how whoosh breaks equal scores.
    scored.sort((a, b) => b.score - a.score || a.docnum - b.docnum);
    const kept = limit === null || limit === undefined ? scored : scored.slice(0, limit);
    return new Results(
      kept.map((s, rank) => new Hit(this.reader, s.docnum, s.score, rank)),
      matched.length,
    );
  }

  documents() {
    return this.reader.allDocIds().map((d) => this.reader.storedFields(d));
  }

  close() {
    this.closed = true;
  }
}

