/**
 * `whoosh.index` -- `create_in()`, `open_dir()` and the `Index` object that
 * hands out writers and searchers.
 *
 * The index is materialised in the directory it is created in: a TOC file
 * records the generation, and each commit writes a segment alongside it.
 */

import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

import { Segment } from './store.mjs';
import { IndexWriter } from './writer.mjs';
import { Searcher } from './searcher.mjs';

const TOC_NAME = '_MAIN.toc';
const SEGMENT_NAME = '_MAIN_1.seg';

export class Index {
  constructor(dirname, schema) {
    this.dirname = dirname;
    this.schema = schema;
    this.generation = 0;
    this._cached = new Segment(schema);
  }

  writer() {
    return new IndexWriter(this);
  }

  searcher() {
    return new Searcher(this);
  }

  docCount() {
    return this._segment().docCount;
  }

  /** @internal called by the writer on commit. */
  _writeSegment(segment) {
    this._cached = segment;
    this.generation += 1;
    writeFileSync(join(this.dirname, SEGMENT_NAME), JSON.stringify(segment.toJSON()), 'utf8');
    writeFileSync(
      join(this.dirname, TOC_NAME),
      JSON.stringify({ generation: this.generation, segment: SEGMENT_NAME, fields: this.schema.names() }),
      'utf8',
    );
  }

  /** @internal the committed segment, re-read from disk when available. */
  _segment() {
    const path = join(this.dirname, SEGMENT_NAME);
    if (this.generation > 0 && existsSync(path)) {
      return Segment.fromJSON(this.schema, JSON.parse(readFileSync(path, 'utf8')));
    }
    return this._cached;
  }
}

/** `create_in(dirname, schema)` -- make a new, empty index in a directory. */
export function createIn(dirname, schema) {
  if (!existsSync(dirname)) mkdirSync(dirname, { recursive: true });
  const index = new Index(dirname, schema);
  writeFileSync(join(dirname, TOC_NAME), JSON.stringify({ generation: 0, fields: schema.names() }), 'utf8');
  return index;
}

/** `open_dir(dirname, schema)` -- re-open an index created earlier. */
export function openDir(dirname, schema) {
  const index = new Index(dirname, schema);
  if (existsSync(join(dirname, SEGMENT_NAME))) index.generation = 1;
  return index;
}

export function existsIn(dirname) {
  return existsSync(join(dirname, TOC_NAME));
}

