/**
 * Node.js port of dataset/test15.py
 *
 *   - build a schema with an analyzed TEXT title, a stored NUMERIC price and an
 *     analyzed TEXT content field
 *   - index two documents in a fresh temporary directory
 *   - parse `--a` as a query against the title field and search
 *   - print the sum of the prices of the matching documents
 */

import { ArgumentParser, str } from './lib/compat/argparse.mjs';
import { pyInt, pyIntStr } from './lib/compat/pyint.mjs';
import { die } from './lib/compat/pyerrors.mjs';
import { mkdtemp } from './lib/compat/tempfile.mjs';
import { Schema, TEXT, NUMERIC } from './lib/fields.mjs';
import { createIn } from './lib/index/index.mjs';
import { QueryParser } from './lib/qparser/parser.mjs';

// argparse reports the converter's name when a value will not convert.
pyInt.typeName = 'int';
str.typeName = 'str';

const parser = new ArgumentParser({ prog: 'test15_executable' });
parser.addArgument('--a', { type: str, required: true });
parser.addArgument('--b', { type: pyInt, required: true });
parser.addArgument('--c', { type: pyInt, required: true });
const args = parser.parseArgs();

try {
  const schema = new Schema({
    title: new TEXT({ stored: true }),
    price: new NUMERIC({ stored: true }),
    content: new TEXT(),
  }); // Create schema with NUMERIC field
  const tempDir = mkdtemp(); // Create temp dir
  const ix = createIn(tempDir, schema); // Create index
  const writer = ix.writer(); // Create writer
  writer.addDocument({ title: args.a, price: args.b, content: 'item1' }); // Add first document
  writer.addDocument({ title: args.a, price: args.c, content: 'item2' }); // Add second document
  writer.commit(); // Commit
  const searcher = ix.searcher(); // Create searcher
  const query = new QueryParser('title', ix.schema).parse(args.a); // Parse query
  const results = searcher.search(query, { limit: 10 }); // Search with limit
  let totalPrice = 0;
  for (const r of results) totalPrice += r.get('price'); // Sum prices from results
  process.stdout.write(pyIntStr(totalPrice) + '\n'); // Print total price
} catch (err) {
  die(err);
}

