// Randomized differential fuzz: reference binary vs the Node port.
import { execFileSync } from 'node:child_process';

const REF = '/workspace/dataset/test15_executable';
const JS = '/output/test15.mjs';

function run(cmd, args) {
  try {
    const out = execFileSync(cmd, args, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
    return { code: 0, out };
  } catch (e) {
    return { code: e.status === null ? -1 : e.status, out: e.stdout ?? '' };
  }
}

const PIECES = [
  'hello', 'world', 'item1', 'item2', 'the', 'and', 'a', 'to', 'xx', 'zz', 'Book', 'CAFE', 'café',
  'AND', 'OR', 'NOT', 'ANDNOT', 'ANDMAYBE', 'REQUIRE', 'TO',
  'title:', 'content:', 'price:', 'foo:', '*', '?', '*:*', '(', ')', '[', ']', '{', '}',
  '"', "'", '^2', '~', '+', '-', ':', '.', '_', '1', '2', '10', '3.14', 'item*', '*item*',
  '[1 TO 5]', '{1 TO 2}', 'item?', '\\', '日本', 'don\'t', 'e.g.', 'C++',
];

function randPiece() {
  return PIECES[Math.floor(Math.random() * PIECES.length)];
}

function randQuery() {
  const n = 1 + Math.floor(Math.random() * 5);
  const parts = [];
  for (let i = 0; i < n; i += 1) parts.push(randPiece());
  return Math.random() < 0.5 ? parts.join(' ') : parts.join('');
}

const NUMS = ['0', '1', '-1', '7', '-42', '2147483647', '-2147483648', '2147483648', '-2147483649',
  '999999999', '1000000000', '007', '+5', ' 3 ', '1_0', '1.5', 'x', '', '1e3', '0x1'];

function randNum() {
  return Math.random() < 0.7
    ? String(Math.floor(Math.random() * 4000000000) - 2000000000)
    : NUMS[Math.floor(Math.random() * NUMS.length)];
}

let pass = 0;
const failures = [];
const iterations = Number(process.argv[2] || 400);

for (let i = 0; i < iterations; i += 1) {
  const args = ['--a', randQuery(), '--b', randNum(), '--c', randNum()];
  const a = run(REF, args);
  const b = run('node', [JS, ...args]);
  if (a.code === b.code && a.out === b.out) pass += 1;
  else failures.push({ args, py: a, js: b });
}

for (const f of failures.slice(0, 25)) {
  console.log('FAIL', JSON.stringify(f.args));
  console.log('  py:', f.py.code, JSON.stringify(f.py.out));
  console.log('  js:', f.js.code, JSON.stringify(f.js.out));
}
console.log(`\npassed=${pass} failed=${failures.length} of ${iterations}`);

