class CompoundQuery extends Query {
  constructor(subqueries, boost = 1.0) {
    super();
    this.subqueries = subqueries;
    this.boost = boost;
  }

  normalizeChildren() {
    return this.subqueries.map((q) => q.normalize());
  }

  score(reader, docnum) {
    return this.subqueries.reduce((acc, q) => acc + q.score(reader, docnum), 0) * this.boost;
  }
}

export class And extends CompoundQuery {
  docs(reader) {
    if (this.subqueries.length === 0) return new Set();
    let acc = null;
    for (const q of this.subqueries) {
      const next = q.docs(reader);
      if (acc === null) acc = next;
      else acc = new Set([...acc].filter((d) => next.has(d)));
      if (acc.size === 0) break;
    }
    return acc ?? new Set();
  }

  normalize() {
    // A NullQuery inside an AND makes the whole conjunction unsatisfiable in
    // whoosh only if it is the sole clause; otherwise it simply drops out.
    const subs = this.normalizeChildren().filter((q) => !q.isNull());
    if (subs.length === 0) return NullQuery;
    if (subs.length === 1) return subs[0];
    return new And(subs, this.boost);
  }

  toString() {
    return `(${this.subqueries.join(' AND ')})`;
  }
}

export class Or extends CompoundQuery {
  docs(reader) {
    const out = new Set();
    for (const q of this.subqueries) for (const d of q.docs(reader)) out.add(d);
    return out;
  }

  normalize() {
    const subs = this.normalizeChildren().filter((q) => !q.isNull());
    if (subs.length === 0) return NullQuery;
    if (subs.length === 1) return subs[0];
    return new Or(subs, this.boost);
  }

  toString() {
    return `(${this.subqueries.join(' OR ')})`;
  }
}

