class CompoundQuery extends Query {
  constructor(subqueries, boost = 1.0) {
    super();
    this.subqueries = subqueries;
    this.boost = boost;
  }

  /**
   * Shared clause cleanup: drop clauses that analyzed away to nothing, and
   * collapse the whole query to `Every` if an unfielded `*:*` is in the mix.
   *
   * @returns {Query|Query[]} a finished query, or the surviving clauses.
   */
  normalizeChildren() {
    const subs = this.subqueries.map((q) => q.normalize());
    if (subs.every((q) => q.isNull())) return NullQuery;
    if (subs.some((q) => q instanceof Every && q.fieldname === null)) return new Every(null, this.boost);
    const kept = subs.filter((q) => !q.isNull());
    if (kept.length === 0) return NullQuery;
    if (kept.length === 1) return kept[0];
    return kept;
  }

  score(reader, docnum) {
    return this.subqueries.reduce((acc, q) => acc + q.score(reader, docnum), 0) * this.boost;
  }
}

