/**
 * Query-syntax nodes.
 *
 * Parsing happens in two phases: a tagging phase turns the raw string into a
 * flat list of these nodes, then a series of filters rearranges them into a
 * tree.  Finally each node knows how to turn itself into a `Query`.
 */

import * as q from '../query/queries.mjs';
import { QueryParserError } from '../compat/pyerrors.mjs';

export class SyntaxNode {
  constructor() {
    this.fieldname = null;
    this.boost = 1.0;
    this.hasFieldname = false;
    this.hasBoost = false;
    this.original = '';
  }

  isText() {
    return false;
  }

  setFieldname(name, override = false) {
    if (!this.hasFieldname) return this;
    if (override || this.fieldname === null) this.fieldname = name;
    return this;
  }

  query() {
    return null;
  }
}

/** Base for anything carrying analyzable text. */
export class TextNode extends SyntaxNode {
  constructor(text) {
    super();
    this.text = text;
    this.original = text;
    this.hasFieldname = true;
    this.hasBoost = true;
    this.tokenize = true;
    this.removestops = true;
    this.qclass = null;
  }

  isText() {
    return true;
  }

  query(parser) {
    const fieldname = this.fieldname || parser.fieldname;
    const termclass = this.qclass || parser.termclass;
    return parser.termQuery(fieldname, this.text, termclass, {
      boost: this.boost,
      tokenize: this.tokenize,
      removestops: this.removestops,
    });
  }
}

export class WordNode extends TextNode {}

/** A `*` or `?` -- merged with neighbouring text by the wildcard filter. */
export class WildcardNode extends TextNode {
  constructor(text) {
    super(text);
    this.tokenize = false;
    this.removestops = false;
    this.qclass = q.Wildcard;
  }
}

export class PrefixNode extends TextNode {
  constructor(text) {
    super(text);
    this.tokenize = false;
    this.removestops = false;
    this.qclass = q.Prefix;
  }
}

/** `"one two three"` */
export class PhraseNode extends SyntaxNode {
  constructor(text, slop = 1) {
    super();
    this.text = text;
    this.original = `"${text}"`;
    this.slop = slop;
    this.hasFieldname = true;
    this.hasBoost = true;
  }

  query(parser) {
    const fieldname = this.fieldname || parser.fieldname;
    if (parser.schema && parser.schema.has(fieldname)) {
      const field = parser.schema.get(fieldname);
      if (field.selfParsing()) {
        try {
          return field.parseQuery(fieldname, this.text, this.boost);
        } catch (err) {
