  /**
   * Shared clause cleanup: drop clauses that analyzed away to nothing, collapse
   * the whole query to `Every` if an unfielded `*:*` is in the mix, and -- once
   * a field is covered by an `Every` -- drop the other clauses on that field,
   * which is how `title:* item?` ends up matching everything.
   *
   * @returns {Query|Query[]} a finished query, or the surviving clauses.
   */
  normalizeChildren() {
    const subs = this.subqueries.map((q) => q.normalize());
    if (subs.every((q) => q.isNull())) return NullQuery;
    if (subs.some((q) => q instanceof Every && q.fieldname === null)) return new Every(null, this.boost);

    const everyfields = new Set();
    for (const q of subs) if (q instanceof Every) everyfields.add(q.fieldname);

    const kept = [];
    const seen = new Set();
    for (const q of subs) {
      if (q.isNull()) continue;
      if (!(q instanceof Every) && everyfields.has(q.field())) continue;
      const key = String(q);
      if (seen.has(key)) continue;
      seen.add(key);
      kept.push(q);
