    for (const q of subs) if (q instanceof Every) everyfields.add(q.fieldname);

    const kept = [];
    const seen = new Set();
    for (const q of subs) {
      if (q.isNull()) continue;
      if (!(q instanceof Every) && everyfields.has(q.field())) continue;
      const key = String(q);
      if (seen.has(key)) continue;
      seen.add(key);
      kept.push(q);
    }
    if (kept.length === 0) return NullQuery;
    if (kept.length === 1) return kept[0];
    return kept;
  }

  field() {
    if (!this.subqueries.length) return null;
    const first = this.subqueries[0].field();
    return this.subqueries.every((q) => q.field() === first) ? first : null;
  }

  score(reader, docnum) {
    return this.subqueries.reduce((acc, q) => acc + q.score(reader, docnum), 0) * this.boost;
  }
}

