/**
 * A faithful subset of CPython's `argparse` -- enough to reproduce
 *
 *     parser = argparse.ArgumentParser()
 *     parser.add_argument('--a', type=str, required=True)
 *     ...
 *     args = parser.parse_args()
 *
 * including the usage line, the `options:` help block, prefix abbreviation
 * matching, `--opt=value` syntax, and the exact wording / exit status (2) of
 * the error messages.
 */

import { pyRepr } from './pyint.mjs';

/** `str` type converter: argparse's default, an identity function. */
export const str = (v) => v;

/** Marker used to give `int` the same `__name__` argparse reports on failure. */
export function typeName(fn) {
  return fn && fn.typeName ? fn.typeName : fn && fn.name ? fn.name : 'type';
}

class Action {
  constructor(optionStrings, dest, { type = str, required = false, help = null, nargs = null } = {}) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.type = type;
    this.required = required;
    this.help = help;
    this.nargs = nargs;
  }

  /** `--a A` / `-h` -- how the option appears in usage and help. */
  formatInvocation() {
    if (this.nargs === 0) return this.optionStrings.join(', ');
    const metavar = this.dest.toUpperCase();
    return this.optionStrings.map((o) => `${o} ${metavar}`).join(', ');
  }

  formatUsage() {
    const first = this.optionStrings[0];
    const part = this.nargs === 0 ? first : `${first} ${this.dest.toUpperCase()}`;
    return this.required ? part : `[${part}]`;
  }
}

export class ArgumentParser {
  constructor({ prog = null, addHelp = true } = {}) {
    this.prog = prog === null ? defaultProg() : prog;
    this.actions = [];
    if (addHelp) {
      this.actions.push(new Action(['-h', '--help'], 'help', { nargs: 0, help: 'show this help message and exit' }));
    }
  }

  addArgument(flags, options = {}) {
    const optionStrings = Array.isArray(flags) ? flags : [flags];
    const dest = optionStrings[0].replace(/^--?/, '').replace(/-/g, '_');
    const action = new Action(optionStrings, dest, options);
    this.actions.push(action);
    return action;
  }

  formatUsage() {
    return `usage: ${this.prog} ${this.actions.map((a) => a.formatUsage()).join(' ')}\n`;
  }

  formatHelp() {
    const invocations = this.actions.map((a) => a.formatInvocation());
    // argparse aligns help text in a column sized by the longest invocation
    // (capped), with a two-space gutter.
    const width = Math.min(Math.max(...invocations.map((s) => s.length)), 24);
    let out = this.formatUsage() + '\noptions:\n';
    this.actions.forEach((action, i) => {
      const inv = invocations[i];
      if (!action.help) out += `  ${inv}\n`;
      else if (inv.length <= width) out += `  ${inv.padEnd(width + 2)}${action.help}\n`;
      else out += `  ${inv}\n${' '.repeat(width + 4)}${action.help}\n`;
    });
    return out;
  }

  error(message) {
    process.stderr.write(this.formatUsage());
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  printHelp() {
    process.stdout.write(this.formatHelp());
  }

  /** Resolve `--pre` to a unique option string, argparse's abbreviation rule. */
  #lookup(optionString) {
    const exact = this.actions.find((a) => a.optionStrings.includes(optionString));
    if (exact) return { action: exact, used: optionString };
    if (!optionString.startsWith('--')) return null;
    const matches = [];
    for (const action of this.actions) {
      for (const os of action.optionStrings) {
        if (os.startsWith(optionString)) matches.push({ action, used: os });
      }
    }
    if (matches.length === 1) return matches[0];
    if (matches.length > 1) {
      const names = matches.map((m) => m.used).join(', ');
      this.error(`ambiguous option: ${optionString} could match ${names}`);
    }
    return null;
  }

  parseArgs(argv = process.argv.slice(2)) {
    const [namespace, extras] = this.parseKnownArgs(argv);
    if (extras.length) this.error(`unrecognized arguments: ${extras.join(' ')}`);
    return namespace;
  }

  parseKnownArgs(argv) {
    const namespace = Object.create(null);
    for (const action of this.actions) {
      if (action.dest !== 'help') namespace[action.dest] = undefined;
    }
    const extras = [];
    const seen = new Set();
    let optionsAllowed = true;

    for (let i = 0; i < argv.length; i += 1) {
      const arg = argv[i];

      if (optionsAllowed && arg === '--') {
        // argparse only swallows the separator if a positional consumes it;
        // this parser declares none, so it falls through to the extras.
        optionsAllowed = false;
        extras.push(arg);
        continue;
      }

      if (!optionsAllowed || !isOptionLike(arg)) {
        extras.push(arg);
        continue;
      }

      const eq = arg.indexOf('=');
      const name = eq === -1 ? arg : arg.slice(0, eq);
      const inlineValue = eq === -1 ? null : arg.slice(eq + 1);
      const hit = this.#lookup(name);
      if (!hit) {
        extras.push(arg);
        continue;
      }
      const { action, used } = hit;

      if (action.dest === 'help') {
        this.printHelp();
        process.exit(0);
      }

      let value = inlineValue;
      if (value === null) {
        const next = argv[i + 1];
        // argparse classifies anything option-shaped as an option, even one it
        // does not recognise, so `--a -:x` is a missing value rather than a value.
        if (next === undefined || isOptionLike(next)) {
          this.error(`argument ${used}: expected one argument`);
        }
        value = next;
        i += 1;
      }

      try {
        namespace[action.dest] = action.type(value);
      } catch (err) {
        this.error(`argument ${used}: invalid ${typeName(action.type)} value: ${pyRepr(value)}`);
      }
      seen.add(action);
    }

    const missing = this.actions.filter((a) => a.required && !seen.has(a)).map((a) => a.optionStrings[0]);
    if (missing.length) this.error(`the following arguments are required: ${missing.join(', ')}`);

    return [namespace, extras];
  }
}

/**
 * Something that starts with `-` and is not a bare `-` or a negative number.
 * argparse only treats `-1` as an option when the parser itself defines
 * negative-number-looking flags, which this one does not.
 */
function isOptionLike(arg) {
  if (!arg.startsWith('-') || arg === '-') return false;
  return !/^-\d+(\.\d*)?$/.test(arg) && !/^-\.\d+$/.test(arg);
}

/** argparse defaults `prog` to `os.path.basename(sys.argv[0])`. */
function defaultProg() {
  const argv0 = process.argv[1] || '';
  const base = argv0.split(/[\\/]/).pop();
  return base || 'prog';
}

