// Fuzz with natural-language-ish inputs: the realistic usage shape.
import { execFileSync } from 'node:child_process';

const REF = '/workspace/dataset/test15_executable';
const JS = '/output/test15.mjs';

function run(cmd, args) {
  try {
    return { code: 0, out: execFileSync(cmd, args, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] }) };
  } catch (e) {
    return { code: e.status === null ? -1 : e.status, out: e.stdout ?? '' };
  }
}

const WORDS = ('laptop phone book widget gadget red blue The Quick Brown Fox jumps over lazy dog ' +
  'Item1 ITEM2 content title price a an it is of on or to us we you your tbd may can yet ' +
  'coffee-mug t-shirt e-mail node.js v1.2.3 42 3.14 100% #tag @user naïve résumé Ünicode ' +
  'ÉCOLE straße 東京 москва مرحبا x y zz ab abc ABCD  ').split(/\s+/).filter(Boolean);

function randTitle() {
  const n = 1 + Math.floor(Math.random() * 6);
  const parts = [];
  for (let i = 0; i < n; i += 1) parts.push(WORDS[Math.floor(Math.random() * WORDS.length)]);
  return parts.join(' ');
}

let pass = 0;
const failures = [];
const iterations = Number(process.argv[2] || 300);
for (let i = 0; i < iterations; i += 1) {
  const args = ['--a', randTitle(), '--b', String(Math.floor(Math.random() * 2000) - 500),
    '--c', String(Math.floor(Math.random() * 2000) - 500)];
  const a = run(REF, args);
  const b = run('node', [JS, ...args]);
  if (a.code === b.code && a.out === b.out) pass += 1;
  else failures.push({ args, py: a, js: b });
}
for (const f of failures.slice(0, 20)) {
  console.log('FAIL', JSON.stringify(f.args));
  console.log('  py:', f.py.code, JSON.stringify(f.py.out));
  console.log('  js:', f.js.code, JSON.stringify(f.js.out));
}
console.log(`\npassed=${pass} failed=${failures.length} of ${iterations}`);

